def main(argv):
    if len(argv)!=1: raise SystemExit(__doc__)
    root=pathlib.Path(argv[0])
    if 'NOSCIVOLO' not in (root/'pillole.js').read_text(encoding='utf-8'):
        raise SystemExit('La copia non è passata da rilascio/r65/applica.py')
    v=json.loads((root/'versioni.json').read_text(encoding='utf-8'))['versioni'][0]['v']
    if v not in ('6.2.4','6.5'): raise SystemExit('Versione non prevista: '+v)
    originali,nuovi={},{}
    for rel,old,new in PATCHES:
        if rel not in originali:
            originali[rel]=(root/rel).read_text(encoding='utf-8')
            nuovi[rel]=originali[rel]
        t=nuovi[rel]
        if new in t: continue
        count=t.count(old)
        if count!=1: raise SystemExit(f'{rel}: attesa 1 occorrenza «{old[:65]}», trovate {count}; nessun file cambiato')
        nuovi[rel]=t.replace(old,new)
    changed=0
    for rel,t in nuovi.items():
        if t!=originali[rel]:
            (root/rel).write_text(t,encoding='utf-8');changed+=1
    print('6.5 · Tabellone e Curva · File cambiati:',changed)

if __name__=='__main__': main(sys.argv[1:])
